/**
 * Seed data of the demo stores as SharedArrays (loaded once, shared read-only by every VU): org1-store1, the default,
 * and org1-store2 (forStore).
 * Only valid where the stack runs with the test-stores profile (local) or test_stores = true (dev).
 */
import { SharedArray } from 'k6/data';

const raw = JSON.parse(open('./seed-org1-store1.json'));

function shared(name) {
  return new SharedArray(`seed:${name}`, () => raw[name]);
}

export const categories = shared('categories');
export const productSlugs = shared('productSlugs');
export const skus = shared('skus');
export const productGroups = shared('productGroups');
export const searchTerms = shared('searchTerms');
export const contentPages = shared('contentPages');
export const menus = shared('menus');
export const policies = shared('policies');

/** Stores with a seed file of their own; every other store browses org1-store1's. */
const org1Store2 = JSON.parse(open('./seed-org1-store2.json'));
const perStore = {
  'org1-store1': { categories, productSlugs, skus, productGroups, searchTerms, contentPages, menus, policies },
  'org1-store2': Object.fromEntries(Object.keys(org1Store2).filter((k) => !k.startsWith('_'))
    .map((k) => [k, new SharedArray(`seed:org1-store2:${k}`, () => org1Store2[k])])),
};

/** The seeded catalogue of one store, by name. */
export function forStore(name) {
  return perStore[name] || perStore['org1-store1'];
}

export function randomOf(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

export function pick(arr, seed) {
  return arr[Math.abs(seed) % arr.length];
}
